ANNOTATIONS = [
    (36, 'after', r'''mapInput：Map 查表 + NOOP 兜底，把 [按键, 处理器] 数组变成查找函数。未绑定的组合键静默通过——不拦截才能让默认分支插入文本。'''),
    (71, 'after', r'''UseTextInputProps 是受控双轨：value 与 offset 都归父组件，本 hook 只通过 onChange/onOffsetChange 上报——PromptInput 要把同样的偏移量喂给补全和 ghost text 渲染。'''),
    (101, 'after', r'''Apple Terminal 预热 modifiers 模块（内部有幂等守卫，可重复调）——那个终端拿修饰键状态要起原生查询，第一次按会卡。'''),
    (105, 'after', r'''cursor 每次渲染从 value+columns+offset 重建（Cursor.fromText）——无内部状态的纯渲染模型，输入处理全是「旧 cursor → 新 cursor」的函数变换。'''),
    (120, 'after', r'''handleCtrlC 三态双击：第一次显示「再按退出」提示，第二次退出，有内容时…实际是 show/exit/clear 三回调。useDoublePress 把「误触防护」做成了可复用原语。'''),
    (153, 'after', r'''handleEscape 与上面的 NOTE(keybindings) 注释：刻意不迁移到键位系统——这是文本级双击行为（连按两次才算），不是动作级键位；双击清空前先把内容 addToHistory（不清历史丢输入是可恢复性设计）。'''),
    (168, 'after', r'''handleEmptyCtrlD：空输入时 Ctrl-D 双击退出（防误触），非空时 Ctrl-D 走 del。'''),
    (178, 'after', r'''handleCtrlD 双面语义：空 = 退出仪式（双击），非空 = 向前删字符（iPython 语义）——一个键两种行为看输入空否。'''),
    (196, 'after', r'''kill ring 四个 kill：Ctrl-K 删到行尾、Ctrl-U 删到行首、Ctrl-W 删前词、Meta+Backspace/Delete。入环方式分 append（Ctrl-K 连续按追加成一条）与 prepend（Ctrl-W 保词序）——emacs kill ring 的标准语义。'''),
    (222, 'after', r'''yank/yankPop：Ctrl-Y 粘贴并记录起始 offset；Alt+Y 替换上次 yank 的内容（不是再插一次）——yankPop 按记录的 start/length 精确切除旧文本再插新的。'''),
    (238, 'after', r'''handleCtrl 的 emacs 键位表。Ctrl-H 优先 deleteTokenBefore（删整个 token：路径、单词）失败才退化成单字符退格——删文件路径时一个 Ctrl-H 删一段而不是一个字符。'''),
    (245, 'after', r'''handleMeta 四键：B/F 词移动、D 删后词、Y yank-pop。'''),
    (267, 'after', r'''handleEnter 三条路径：① 行尾反斜杠 = 续行（backspace+insert \n，markBackslashReturnUsed 记埋点）；② Meta/Shift+Enter = 换行；③ Apple Terminal 不支持自定义 Shift+Enter，改用原生修饰键检测（isModifierPressed）——每个终端的能力差异都在这一层抹平。'''),
    (316, 'after', r'''upOrHistoryUp/downOrHistoryDown 三级降级：先按折行移动（视觉行）→ 多行输入再试逻辑行（段落边界）→ 都动不了才触发历史导航。disableCursorMovementForUpDownKeys 时直接走历史（某些面板要方向键干别的）。'''),
    (413, 'after', r'''mapKey 的 switch(true) 链就是优先级链，注释点明两个关键顺序：① key.return 必须早于 key.meta——否则 Option+Return 被 meta 分支吞掉变不了换行；② escape 分支靠 disableEscapeDoublePress 外部关断——注释解释为什么不能指望 stopImmediatePropagation：BaseTextInput 的 useInput 先注册（子 effect 先于父 effect 跑），等键位处理器停传播时本处理器已经跑完了，只能靠外部布尔协作。pageUp/Down 和 wheel 在 fullscreen 模式让位给 ScrollKeybindingHandler（NOOP 而不是吞掉——裸 SGR 序列不能当文本插进去）。'''),
    (424, 'after', r'''isKillKey：Ctrl-K/U/W 与 Meta+Backspace/Delete 是 kill——连续按要合并进 kill ring 累积，非 kill 键打断累积（resetKillAccumulation）。'''),
    (429, 'after', r'''isYankKey：Ctrl+Y/Alt+Y 延续 yank-pop 链，其他键断链（resetYankState）。'''),
    (501, 'after', r'''onInput 全流程：① inputFilter 过滤（被滤掉就什么都不做）② \x7f DEL 处理（#1853：SSH/tmux 里退格同时产生按键事件和裸 DEL 字符，同步把每个 DEL 应用成 deleteTokenBefore ?? backspace，最后一次性 onChange）③ kill/yank 状态重置 ④ mapKey 求下一 cursor ⑤ 文本真变了才 onChange、offset 无条件同步 ⑥ SSH 合并 Enter 检测（长度>1、尾 \r、前面无 \r、前字符非反斜杠 → submit）。'''),
    (509, 'after', r'''ghostTextForRender 的陈旧防护：inlineGhostText.insertPosition 必须等于当前 offset 才渲染——ghost 状态是 useEffect 后更新的，不比对就会拿上个击键的 ghost 闪一帧。'''),
    (529, 'after', r'''返回五件套：onInput + renderedValue（带 mask/invert/ghost 的最终字符串）+ offset 双轨 + 四个视口字段（外层滚动要按它们算可见区）。'''),
]
